CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('admin','moderator')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.kalzo_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.kalzo_is_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.kalzo_is_admin() TO authenticated;
ALTER TABLE public.artist_profiles ADD COLUMN photo_path text NOT NULL DEFAULT '', ADD COLUMN instagram text NOT NULL DEFAULT '', ADD COLUMN primary_reel integer NOT NULL DEFAULT 0, ADD COLUMN state_name text NOT NULL DEFAULT '', ADD COLUMN current_city text NOT NULL DEFAULT '', ADD COLUMN preferred_cities text[] NOT NULL DEFAULT '{}', ADD COLUMN travel_setting text NOT NULL DEFAULT 'excluding', ADD COLUMN pricing_unit text NOT NULL DEFAULT 'hour', ADD COLUMN verification_status text NOT NULL DEFAULT 'not_started', ADD COLUMN availability jsonb NOT NULL DEFAULT '[]';
CREATE FUNCTION public.kalzo_protect_artist_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user NOT IN ('postgres','service_role') AND NOT public.kalzo_is_admin() THEN IF TG_OP='INSERT' THEN IF NEW.verification_status <> 'not_started' THEN RAISE EXCEPTION 'Identity verification must come from the verification provider'; END IF; ELSIF NEW.verification_status IS DISTINCT FROM OLD.verification_status THEN RAISE EXCEPTION 'Identity verification cannot be self-approved'; END IF; END IF; IF NEW.status='approved' AND (NEW.verification_status <> 'verified' OR jsonb_array_length(NEW.reels)<2 OR jsonb_array_length(NEW.reels)>4 OR NEW.photo_path='') THEN RAISE EXCEPTION 'Verified identity, photo and 2 to 4 reels are required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER kalzo_protect_artist_verification BEFORE INSERT OR UPDATE ON public.artist_profiles FOR EACH ROW EXECUTE FUNCTION public.kalzo_protect_artist_verification();
CREATE POLICY admin_artist_read ON public.artist_profiles FOR SELECT TO authenticated USING(public.kalzo_is_admin());
CREATE POLICY admin_artist_update ON public.artist_profiles FOR UPDATE TO authenticated USING(public.kalzo_is_admin()) WITH CHECK(public.kalzo_is_admin());
CREATE POLICY admin_patron_read ON public.profiles FOR SELECT TO authenticated USING(public.kalzo_is_admin());
CREATE POLICY admin_booking_read ON public.bookings FOR SELECT TO authenticated USING(public.kalzo_is_admin());
ALTER TABLE public.bookings ADD COLUMN artist_owner_id uuid, ADD COLUMN workflow_stage text NOT NULL DEFAULT 'awaiting_payment', ADD COLUMN quantity integer NOT NULL DEFAULT 1, ADD COLUMN event_at timestamptz, ADD COLUMN venue_video_path text NOT NULL DEFAULT '', ADD COLUMN acceptance_video_path text NOT NULL DEFAULT '', ADD COLUMN payout_status text NOT NULL DEFAULT 'not_due', ADD COLUMN refund_status text NOT NULL DEFAULT 'none', ADD COLUMN payment_order_id text UNIQUE, ADD COLUMN payment_id text UNIQUE;
CREATE POLICY artist_booking_read ON public.bookings FOR SELECT TO authenticated USING(artist_owner_id=auth.uid());
CREATE TABLE public.booking_codes (booking_id uuid PRIMARY KEY REFERENCES public.bookings(id) ON DELETE CASCADE, arrival_code text NOT NULL, closing_code text NOT NULL, expires_at timestamptz NOT NULL, arrival_used boolean NOT NULL DEFAULT false, closing_used boolean NOT NULL DEFAULT false, arrival_attempts integer NOT NULL DEFAULT 0, closing_attempts integer NOT NULL DEFAULT 0);
GRANT ALL ON public.booking_codes TO service_role;
ALTER TABLE public.booking_codes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.support_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, category text NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.support_threads TO authenticated; GRANT ALL ON public.support_threads TO service_role;
ALTER TABLE public.support_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_support_read ON public.support_threads FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY own_support_insert ON public.support_threads FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());
CREATE POLICY admin_support_read ON public.support_threads FOR SELECT TO authenticated USING(public.kalzo_is_admin());
CREATE TABLE public.support_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.support_threads(id) ON DELETE CASCADE, sdk_id text NOT NULL, message jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id,sdk_id));
GRANT SELECT ON public.support_messages TO authenticated; GRANT ALL ON public.support_messages TO service_role;
ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_support_messages_read ON public.support_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.support_threads WHERE id=thread_id AND owner_id=auth.uid()));
CREATE POLICY admin_support_messages_read ON public.support_messages FOR SELECT TO authenticated USING(public.kalzo_is_admin());
CREATE POLICY own_media_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='kalzo-media' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY own_media_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='kalzo-media' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.kalzo_is_admin() OR EXISTS(SELECT 1 FROM public.bookings b WHERE b.patron_id=auth.uid() AND (b.venue_video_path=name OR b.acceptance_video_path=name))));
CREATE FUNCTION public.kalzo_public_artists() RETURNS TABLE(id uuid, stage_name text, discipline text, base_city text, state_name text, bio text, rate_inr integer, instagram text, primary_reel integer, pricing_unit text, current_city text, preferred_cities text[], travel_setting text, availability jsonb) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id,stage_name,discipline,base_city,state_name,bio,rate_inr,instagram,primary_reel,pricing_unit,current_city,preferred_cities,travel_setting,availability FROM public.artist_profiles WHERE status='approved' AND verification_status='verified' $$;
REVOKE ALL ON FUNCTION public.kalzo_public_artists() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.kalzo_public_artists() TO anon,authenticated;